// Extract generated code and parse files
const response = items[0].json.response;

// Split by file markers
const fileRegex = /# FILE: ([\w\/\.]+)\n([\s\S]*?)(?=# FILE:|$)/g;
const files = [];
let match;

while ((match = fileRegex.exec(response)) !== null) {
  files.push({
    filename: match[1],
    content: match[2].trim()
  });
}

return [{
  json: {
    agent: 'Johnie',
    user_story: items[0].json.user_story,
    files: files,
    raw_response: response,
    timestamp: new Date().toISOString()
  }
}];

// Aggregate all results
const johnieData = $node['Parse Generated Files'].json;
const borisData = $node['Boris: Security Review'].json;
const lindaData = $node['Linda: Write Tests'].json;

// Extract approval status from Boris review
const borisReview = borisData.response;
const isApproved = borisReview.includes('APPROVED') && !borisReview.includes('NEEDS_FIXES');
const hasCritical = borisReview.includes('SEVERITY: Critical');

return [{
  json: {
    sprint_result: {
      user_story: johnieData.user_story,
      code_files: johnieData.files,
      security_review: {
        agent: 'Boris',
        approved: isApproved,
        has_critical: hasCritical,
        full_review: borisReview
      },
      tests: {
        agent: 'Linda',
        test_code: lindaData.response
      },
      status: isApproved && !hasCritical ? 'READY_FOR_DEPLOYMENT' : 'NEEDS_REVISION',
      timestamp: new Date().toISOString(),
      agents_involved: ['Johnie', 'Boris', 'Linda']
    }
  }
}];
